export function getOccasionsForCategory(categoryId: string): Occasion[] {
  return occasions[categoryId] || [];
}

export function getOccasionById(categoryId: string, occasionId: string): Occasion | undefined {
  const categoryOccasions = occasions[categoryId];
  return categoryOccasions?.find(occasion => occasion.id === occasionId);
}
